#!/usr/bin/env python3
"""Generate a makepkg-compatible .MTREE manifest for an Arch package root.

Why this exists: the v2.2.15 arch job died with "ERROR: mtree (libarchive)
missing" — Arch's `libarchive` package ships bsdtar/bsdcpio/bsdcat but NOT
the netbsd `mtree` binary, so the hand-rolled packaging step could never
produce the .MTREE that libalpm requires (without it pacman reports
"faltando metadados do pacote / pacote inválido ou corrompido").

Output format matches makepkg exactly (observed against real community
packages):
    # Generated by pacman 6.1.0
    # Built on <date -u output>
    # Built by root
    . type=dir uid=0 gid=0 mode=0755 time=<epoch>.000000000 size=4096
    usr  type=dir uid=0 gid=0 mode=0755 time=... size=4096
    usr/bin/qwen-studio  type=file uid=0 gid=0 mode=0755 size=N time=... sha256digest=<hex> xattr=()
Entries are emitted in byte-wise sorted order (what LC_ALL=C find|sort gives),
directories include size=4096, files include sha256digest. The caller pipes
stdout through `gzip -9 -n`.

Usage: python .mtree-gen.py <pkgroot> > manifest
"""
import hashlib
import os
import stat
import sys
from datetime import datetime, timezone


def entry_lines(root):
    lines = []
    # Header, identical in shape to makepkg's.
    now = datetime.now(timezone.utc).strftime("%a %b %d %H:%M:%S UTC %Y")
    lines.append("# Generated by pacman 6.1.0")
    lines.append(f"# Built on {now}")
    lines.append("# Built by root")

    def common(path):
        st = os.lstat(path)
        return (st, f"uid={st.st_uid} gid={st.st_gid} "
                    f"mode=0{oct(stat.S_IMODE(st.st_mode))[2:]} "
                    f"time={st.st_mtime:.9f}")

    # "." first, as makepkg emits it before descending.
    st, base = common(root)
    lines.append(f". type=dir {base} size=4096")

    entries = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = os.path.relpath(dirpath, root)
        if rel_dir != ".":
            entries.append(("dir", rel_dir))
        for f in filenames:
            fp = os.path.join(dirpath, f)
            entries.append(("file", os.path.relpath(fp, root)))
    # Byte-wise sort like LC_ALL=C sort (paths compared as UTF-8 bytes).
    entries.sort(key=lambda e: e[1].encode("utf-8"))
    for kind, rel in entries:
        full = os.path.join(root, rel)
        st, base = common(full)
        if kind == "dir":
            lines.append(f"{rel} type=dir {base} size=4096")
        else:
            digest = hashlib.sha256(open(full, "rb").read()).hexdigest()
            lines.append(
                f"{rel} type=file {base} size={st.st_size} "
                f"sha256digest={digest} xattr=()"
            )
    return lines


def main():
    if len(sys.argv) != 2:
        print(__doc__, file=sys.stderr)
        return 2
    root = sys.argv[1]
    if not os.path.isdir(root):
        print(f"mtree-gen: not a directory: {root}", file=sys.stderr)
        return 1
    sys.stdout.write("\n".join(entry_lines(root)) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
